module bus_ticketing_system #(parameter SEATS=32)(input wire clk,rst_n,book,cancel,input wire [7:0] passenger_id,output reg accepted,cancelled,output reg [7:0] last_passenger,output reg [$clog2(SEATS+1)-1:0] seats_left); always @(posedge clk or negedge rst_n) begin if(!rst_n)begin seats_left<=SEATS;last_passenger<=0;accepted<=0;cancelled<=0;end else begin accepted<=0;cancelled<=0;if(book&&seats_left!=0)begin seats_left<=seats_left-1'b1;last_passenger<=passenger_id;accepted<=1;end else if(cancel&&seats_left<SEATS)begin seats_left<=seats_left+1'b1;cancelled<=1;end end end endmodule
